const GLOSSARY=[
gl("Atacar","Acción","Asignar Aliados de la Línea de Defensa para dañar el Mazo Castillo rival, moviéndolos a la Línea de Ataque.","Mueves a tu Aliado a la Línea de Ataque y empieza la Batalla Mitológica.","mi-hel","oficial"),
gl("Bloquear","Acción","Asignar un Aliado de la Línea de Defensa para detener a un atacante. Cada bloqueo va de un defensor a un único atacante.","","mi-hel","oficial"),
gl("Botar","Acción","Poner en el Cementerio la cantidad indicada de cartas del tope del Castillo.","Botar 3 = tres cartas del tope al Cementerio.","mi-hel","oficial"),
gl("Descartar","Acción","Poner una carta de la mano en el Cementerio.","","mi-hel","oficial"),
gl("Desterrar","Acción","Enviar una carta de cualquier zona de juego a la Zona de Destierro.","","mi-hel","oficial","Las cartas desterradas por lo general no vuelven a usarse en el duelo."),
gl("Destruir","Acción","Eliminar una carta en juego poniéndola en su Cementerio.","","mi-hel","oficial","No es lo mismo que Desterrar."),
gl("Robar","Acción","Tomar la carta del tope del Castillo y ponerla en la mano.","","mi-hel","oficial"),
gl("Fuerza","Atributo","Número impreso en la esquina superior izquierda del Aliado; es el daño que asigna. Suma el valor impreso más modificadores.","","mi-hel","oficial"),
gl("Imbloqueable","Habilidad","Este Aliado no puede ser bloqueado.","","mi-hel","oficial"),
gl("Indestructible","Habilidad","La carta no puede ser destruida mientras está en juego.","","mi-hel","oficial","El glosario solo la protege de 'destruir'."),
gl("Indesterrable","Habilidad","La carta no puede ser desterrada mientras está en juego.","","mi-hel","oficial"),
gl("Oro Inicial","Habilidad","Permite usar ese oro como primer oro al iniciar la partida.","","mi-hel","oficial"),
gl("Generar Oros","Mecánica","Oros producidos por una habilidad; duran normalmente solo el turno en que aparecen y no cuentan como oros en una zona de juego.","","mi-hel","oficial"),
gl("Batalla Mitológica","Mecánica","Fase de combate que se inicia al declarar el ataque de al menos un Aliado. Pasos: Declaración de Ataque, de Bloqueo, Guerra de Talismanes y Asignación de Daño.","","mi-hel","oficial"),
gl("Guerra de Talismanes","Mecánica","Paso de la batalla donde se juegan Talismanes alternadamente, empezando por quien bloquea.","","mi-hel","oficial"),
gl("Portar (Arma)","Mecánica","Tras pagarla, el Arma se pone tras un Aliado en juego. Solo se juega sobre Aliados y no se transfiere.","","mi-hel","oficial","Según la FAQ, el Arma sigue al Aliado cuando éste cambia de zona (ej. sube a la mano con Santo Grial)."),
gl("Para (requisito)","Redacción","Marca una condición o requisito para poner la carta en juego; siempre debe cumplirse.","'Para que Kurick, el Picto entre en juego, debes destruir 2 Oros.'","faq23","oficial"),
gl("Cuando (disparada)","Redacción","Caracteriza habilidades disparadas: no son condición de juego y ocurren una vez que la carta está en juego.","'Cuando Dragón de Magma entra en juego, destruye un Aliado oponente.'","faq23","oficial"),
gl("Considerar","Redacción","Efecto que añade un tipo de carta al ya existente, sin quitar el original.","Mercaderes que bloquea se considera Aliado y Oro a la vez.","faq23","oficial"),
gl("Transformar / Convertir","Redacción","Para el juego son idénticos: cambian el tipo de carta; deja de ser el tipo anterior mientras dure el efecto.","Ave de Hera deja de ser Oro y pasa a ser Aliado.","faq23","oficial"),
gl("Prevención","Mecánica","Acción de evitar que una carta salga del juego por una habilidad, efecto o comparación de fuerza (solo Aliados). No es una habilidad 'en respuesta'.","Puede ejecutarse después de comparar fuerzas entre dos Aliados.","faq23","oficial","No se ve afectada por cartas que limitan 'respuestas', como Micenas."),
gl("Redirección","Mecánica","Se juega justo después de que el oponente juega una carta o activa una habilidad; cambia el objetivo, y el nuevo objetivo debe ser válido. Los efectos globales no se redirigen.","Relámpago Arcano redirige 'destruye una carta que no sea Oro' de Bola de Fuego.","faq23","oficial"),
gl("Autorreferencia","Regla","La fuente de un efecto nunca puede ser objetivo del mismo efecto (DAR 4.6.11, citado por la FAQ).","Neferite I no puede desterrarse a sí mismo con su propia habilidad.","faq23","oficial"),
gl("Efecto global / universal","Regla","Efecto que no apunta a un objetivo concreto; por regla general no puede ser redirigido.","Aplastar Fomor, Kenneth I, Thanatos, Eolo.","faq23","oficial"),
gl("Habilidad activada","Tipo de habilidad","No es opcional salvo que el texto diga 'Puedes' (DAR 6.2.2).","","dar","oficial","Basado en fragmento del DAR; versión no verificada."),
gl("Habilidad disparada","Tipo de habilidad","Se identifica por las palabras 'Si' o 'Cuando' en la caja de texto (DAR 6.3.1).","","dar","oficial","Basado en fragmento del DAR."),
gl("Habilidad continua","Tipo de habilidad","Se identifica por 'Mientras' (DAR 6.4.2). No se puede cancelar: solo habilidades activadas o disparadas.","Siete contra Tebas no cancela habilidades continuas.","dar","oficial","Parte de la nota viene de la FAQ 2023."),
gl("Habilidad permanente","Tipo de habilidad","Se identifica por 'Permanentemente' (DAR 6.5.1).","","dar","oficial","Basado en fragmento del DAR."),
gl("Anular / Cancelar","Mecánica","Según la FAQ, anular afecta a Talismanes y cancelar a habilidades de cartas en juego.","Cárcel para el Mal anula un Talismán o cancela una habilidad oponente.","faq23","oficial","Una fuente comunitaria también distingue ambos términos."),
gl("Carta Única","Construcción","Es una habilidad de construcción de mazo, no de juego: no impide jugar una copia más durante la partida.","","faq23","oficial","Distinta de 'Solo puedes controlar una copia de esta carta'."),
gl("Concordancia de nombres","Regla","Basta coincidir la raíz del nombre; 'carta Goblin' incluye cualquier carta cuyo nombre contenga exactamente Goblin.","Goblin Stone, Goblin Maligno… pero no Hobgoblin.","faq23","oficial"),
gl("Embestida X","Habilidad","Cada vez que este Aliado es bloqueado, el defensor bota X cartas.","","es-tl","comunidad","No confirmado en Primer Bloque vigente."),
gl("Evasión X","Habilidad","Cada vez que este Aliado bloquea, baraja X cartas de tu cementerio en tu castillo.","","es-tl","comunidad","No confirmado en Primer Bloque vigente.","Sin verificar"),
gl("Inmunidad X","Habilidad","El Aliado no puede ser afectado por habilidades del tipo X.","","es-tl","comunidad","No confirmado en Primer Bloque vigente.","Sin verificar"),
gl("Maquinaria","Habilidad","Arma que va en Línea de Apoyo y solo usa sus habilidades si controlas al menos un Aliado.","","es-tl","comunidad","No confirmado en Primer Bloque vigente.","Sin verificar"),
gl("Orbe","Habilidad","Solo puede ser destruida por cartas que destruyan Orbes específicamente.","","es-tl","comunidad","No confirmado en Primer Bloque vigente.","Sin verificar")];
const R=(id,t,txt,tags,src,tipo)=>({id,t,txt,tags,src:src||"mi-hel",tipo:tipo||"oficial",ed:PB,k:"regla"});
const RULES=[
R("r-turno","Fases del turno","Orden: Agrupación, Vigilia, Final y Robar. La Batalla Mitológica ocurre dentro de la Vigilia al declarar ataque con al menos un Aliado.","turno fase agrupacion vigilia final robar orden"),
R("r-agrup","Fase de Agrupación","Devuelve a la Reserva los oros del Oro Pagado y regresa a la Línea de Defensa a los Aliados de la Línea de Ataque.","agrupacion oro pagado reserva linea"),
R("r-vigilia","Fase de Vigilia","Puedes usar habilidades de cartas en juego o jugar otras. Al iniciar, puedes poner un oro de tu mano en la Reserva, solo en ese momento salvo que una carta diga otra cosa.","vigilia oro mano jugar habilidades"),
R("r-final","Fase Final","Terminan los efectos 'hasta la Fase Final' (salvo que se indique otra cosa) y luego se pasa a Robar. El DAR 5.4 detalla el orden de término de efectos.","final duracion efectos terminan turno"),
R("r-robar","Robar y límite de mano","Robas una carta al cerrar el turno. Máximo 8 cartas en mano, pero solo en la Fase de Robar debes descartar el exceso.","robar mano limite ocho descartar"),
R("r-jugar","Pasos para jugar una carta","1) Pagar el coste (Reserva → Oro Pagado). 2) Poner la carta en su zona. 3) Designar objetivos. 4) Si entra en juego, usar sus habilidades. Un Aliado debe pasar por una Agrupación bajo tu control para atacar (DAR 4.5.3).","jugar carta coste pagar objetivos pasos zona atacar recien"),
R("r-batalla","Pasos de la Batalla Mitológica","Declaración de Ataque, Declaración de Bloqueo, Guerra de Talismanes y Asignación de Daño.","batalla mitologica ataque bloqueo talismanes dano"),
R("r-guerra","Orden en Guerra de Talismanes","Se juegan Talismanes alternadamente, parte quien bloquea. Habilidades sin 'En tu Fase de Vigilia' pueden usarse también aquí; con 'una vez por turno' sirven en Vigilia o en Guerra de Talismanes.","guerra talismanes orden alternada respuesta vigilia"),
R("r-dano","Asignación de daño","Atacante mayor: bloqueador destruido y la diferencia se bota del Castillo. Igual: ambos destruidos. Menor: atacante destruido. El daño de todos los Aliados se suma y se cobra de forma consolidada.","dano fuerza bloqueo destruido castillo igual consolidado"),
R("r-talisman","Talismanes","Al jugarse van al Cementerio aunque su efecto no se resuelva; suelen ser de efecto inmediato y uso único.","talisman cementerio inmediato"),
R("r-totem","Tótems","Van a la Línea de Apoyo y dan bonificaciones continuas; las cartas de esa línea no pueden bloquear.","totem linea apoyo continuo"),
R("r-arma","Armas","Solo sobre Aliados, no se transfieren, y dan bonificación mientras Arma y Aliado sigan en juego.","arma portar aliado"),
R("r-victoria","Victoria y derrota","Pierde quien se queda sin cartas en el Castillo. Solo los Aliados dañan el Castillo rival mediante ataque (el daño directo de cartas es aparte). Si ambos quedan en 0 al mismo tiempo, es empate (FAQ).","victoria castillo derrota empate"),
R("r-inicio","Preparación","Un oro inicial a la Reserva, Castillo barajado de 50 cartas, robar hasta 8; puedes devolver la mano y robar una menos. Quien empieza se decide al azar.","inicio preparacion mano castillo"),
R("r-texto","El texto de la carta manda","Si una habilidad contradice el DAR, prevalece el texto de la carta.","texto carta prioridad contradice dar excepcion regla general","dar"),
R("r-impresion","Qué impresión vale","Por regla general vale la última impresión de una carta, salvo que se indique lo contrario o haya un error evidente de impresión.","reimpresion errata ultima impresion version","faq23"),
R("r-fmt","Formatos de Primer Bloque","Libre/Full (todas las cartas), Racial soporte libre, Racial soporte edición, Ragnarok (todas las cartas se tratan como Carta Única). Existen 12 razas de Aliados repartidas en las 4 ediciones.","formato libre full racial ragnarok razas","faq23"),
R("r-ext","Primer Bloque Extendido","Formato que permite todas las cartas desde 'El Reto' hasta 'Espíritu de Dragón', con las restricciones que fije cada evento oficial.","formato extendido reto espiritu dragon")];
const F=(card,txt,tags)=>({id:"f-"+card.toLowerCase().replace(/\W+/g,"-"),t:card,card,txt,tags:(tags||"")+" "+card,src:"faq23",tipo:"aclaración oficial",ed:PB+" · FAQ sept. 2023",k:"aclaración"});
const FAQ=[
F("Relámpago Arcano","Es una Redirección: se juega justo después de que el oponente juega o activa algo que afecte a una carta tuya que no sea Oro. El nuevo objetivo debe ser válido y no se pueden redirigir efectos globales (Kenneth I, Thanatos, Aplastar Fomor). Por autorreferencia, la fuente (ej. Neferite I) no puede ser el nuevo objetivo.","redirigir redireccion objetivo global"),
F("Escudo de Atenea","Su habilidad es una Redirección, por lo que el portador no es afectado; el nuevo objetivo debe ser válido y los efectos globales (Eolo, Rayos) no se redirigen.","redireccion"),
F("Antropófagos","No se puede jugar sobre un Aliado Indestructible, porque no podría destruirse en la Fase Final (se exige un objetivo válido). Sí sobre Aliados que solo tienen Prevención (como Ra o Rey Arturo Pendragón).","indestructible destruir fase final objetivo"),
F("Arde Troya","Tiene errata: anula o cancela una carta que afecte a Oros en juego y, si fue cancelada, la destruye; si se juega en turno rival, éste pasa a su Fase Final.","anular cancelar oros"),
F("Kenneth I","Solo puede nombrar cartas en juego; los Talismanes no entran en juego. Su efecto es global y no puede redirigirse.","global talisman nombrar"),
F("Boobrie","Solo puedes jugar uno en respuesta a una declaración de ataque, porque activar múltiples habilidades en respuesta aplica solo a cartas en juego. Debe ser declarado bloqueador. Con Macha o Serpiente Roja en juego no se destruye en la Fase Final.","respuesta ataque bloquear multiples"),
F("Letanía","Es una prevención: se activa justo después de que uno de tus Oros sea afectado por una habilidad oponente (incluida Letanía).","prevencion oros"),
F("Averix el Sabio","Con errata: el oponente no puede activar habilidades que duren hasta el Final del Turno o la Fase Final, aunque no lo diga explícitamente. No afecta a Talismanes.","duracion fase final habilidades"),
F("Niña de la Suerte","Las cartas mostradas deben cumplir todos sus requisitos y costes adicionales. Si ambas tienen habilidades disparadas, ambas se disparan, empezando por el jugador que jugó Niña de la Suerte.","disparada orden"),
F("Sehetepibre","Puede atacar, pero no hace ambos daños: o su fuerza pasa como daño de combate, o se destruye para hacer daño directo equivalente.","daño directo combate"),
F("Guiza","Por autorreferencia no puede considerarse Aliado a sí misma; solo atacaría si otro efecto la vuelve Aliado.","autorreferencia"),
F("Takelot","Si Takelot o Temístocles pierden su habilidad, las cartas que nombraron recuperan la suya; si la recuperan, las cartas nombradas la pierden otra vez.","perder habilidad nombrar"),
F("Temístocles","Si pierde su habilidad, las cartas nombradas por él recuperan la suya (igual que Takelot).","perder habilidad nombrar"),
F("Hestia","El daño de varios atacantes se consolida en la Asignación de Daño; con 3 atacantes, Hestia hace solo 3 de daño.","daño asignacion consolidado"),
F("Ave de Hera","Puede pagarse a sí misma para transformarse y atacar; en la Fase Final vuelve a la zona de origen. Mientras es Aliado pierde el tipo Oro y puede ser destruida (ej. Bola de Fuego).","convertir oro aliado transformar"),
F("Horda Fomoré","Con errata: solo puedes activar una Horda Fomoré por turno.","una vez por turno"),
F("Chike de la Sombra","No puede jugarse en Guerra de Talismanes: su habilidad no tiene gatillante de fase y solo se activa en la Fase de Vigilia de su dueño.","guerra talismanes cementerio vigilia"),
F("Gran Khopesh","Si el portador es destruido, la habilidad no se resuelve, porque el Arma debe estar en juego.","arma portador destruido"),
F("Brian Boru","Puede mover a la Línea de Ataque a un Aliado que solo puede bloquear, pues solo lo mueve de zona sin declararlo atacante.","declarar atacante mover"),
F("Caturix","Baraja HASTA cuatro cartas, combinando oros y Aliados Desafiantes; nunca más de cuatro, pero puedes elegir menos.","hasta barajar"),
F("Heka","Si pagaste 1 oro y el Aliado sale del juego, igual robas en la Fase Final: el efecto ya fue pagado y es obligatorio.","fase final robar pagado"),
F("Príncipe Djedi","No puede destruirse a sí mismo para hacer daño, por autorreferencia.","autorreferencia daño"),
F("Corona Faraónica","Un Aliado que acaba de entrar y es el primero en juego no recibe el beneficio si no controlas otro Aliado Faraón.","atacar recien jugado faraon"),
F("Kilgharrah","El efecto debe cumplirse completo: barajas 2 y robas 2; si no puedes barajar 2, no robas.","completo efecto barajar robar"),
F("Lanza Divina","Las habilidades que no dicen 'En tu Fase de Vigilia' se pueden usar en Guerra de Talismanes del turno oponente; 'una vez por turno' vale en ambas.","guerra talismanes turno oponente"),
F("Orium","Tiene dos habilidades independientes: el turno que ataca debe destruirse en la Fase Final; si no ataca, no se destruye por esa habilidad.","fase final atacar destruir"),
F("Tormenta de Dragón","Debe resolverse para desterrar el Aliado: los objetivos se declaran al jugarla y deben ser válidos; si el Talismán es anulado, no destierras.","anulado talisman objetivo resolver"),
F("Merlín","Un Talismán jugado por su efecto va al Destierro aunque sea anulado.","anular destierro"),
F("Círculo Eterno","Da la habilidad Carta Única (de construcción), por lo que puedes jugar otra copia; al entrar debe quedar una copia de cada carta en juego.","carta unica"),
F("Wyvern","Cualquier carta que destruya a Wyvern debe ser desterrada (Bola de Fuego, Fergus, Aliado bloqueador en asignación de daño).","destruir desterrar"),
F("Capa de Invisibilidad","No puede jugarse sobre Helios, Dendera ni Seshat. Los dos primeros no pueden ser afectados por Talismanes oponentes; Seshat deja un Arma en juego que impide barajarla.","inmune talisman"),
F("Santo Grial","Para resolver el efecto la carta debe ser destruida: sube un Aliado destruido a la mano, pero el efecto de la carta que lo destruyó (ej. Morgana) no se resuelve. El Arma portada sigue al Aliado.","destruido subir mano arma"),
F("Nimue","Su copia termina al inicio de la Fase Final, por lo que no puedes robar con Bruja Anis en esa fase. Con Red de Aracne no puede copiar. Si le quitan la habilidad a lo copiado, queda fuerza cero.","copiar fase final"),
F("Siete contra Tebas","Puede cancelar habilidades activadas o disparadas de cartas en juego (por ejemplo Tuatha de Danaan tras pagar su coste), pero no habilidades continuas.","cancelar continua activada disparada"),
F("Nemty","No puede destruirse a sí mismo para barajar una carta oponente (autorreferencia, DAR 4.6.11).","autorreferencia"),
F("Neferite I","Puede desterrar cartas de coste cero (cero es un coste), pero no puede hacerse objetivo a sí mismo.","coste cero autorreferencia"),
F("Kurick, el Picto","Destruir los Oros es una condición para jugarlo: no puedes destruir los oros usados para pagar su coste; necesitas al menos 4 oros en juego.","para condicion coste oros"),
F("Amón","Cada vez que lo hacen objetivo (incluso con Talismanes como Bola de Fuego) debe pagarse el coste adicional.","objetivo coste adicional"),
F("Gruagash","Al entrar baraja a los demás Aliados; si Akenathon está en juego, solo se baraja Akenathon y los demás permanecen.","prevenir afectar baraja"),
F("Haquika","Si le juegas Guardia Gozosa, ya no tiene la habilidad de devolver el Aliado al salir del juego.","perder habilidad control"),
F("Ramsés II","Si es bloqueado por Figol el Druida, puede disparar su habilidad en respuesta al bloqueo y hacer pasar el daño: Figol no cancela el ataque, solo regresa a los atacantes a la Línea de Defensa.","bloqueo atacante daño"),
F("Goblin","Con 3 o más cartas Goblin, solo el Aliado Goblin exacto es Imbloqueable; no se extiende a Goblin Conjugador ni Goblins Navideños.","concordancia nombres imbloqueable"),
F("Mewn","No puede elegirse a sí mismo para ganar Fuerza e Imbloqueable (autorreferencia).","autorreferencia imbloqueable"),
F("Goblin Maligno","Su efecto se dispara en respuesta a declarar ataque; si luego juegan Congelar, ya no cambia la bonificación recibida. El jugador activo tiene la prioridad en ese caso.","prioridad respuesta ataque"),
F("Qadesh","Cuchulain puede salvarse destruyendo a otro Defensor, porque es Prevención y se antepone al efecto de Qadesh.","prevencion destruir masivo"),
F("Crear Fungoides","Se pueden buscar Aliados Indestructibles/Indesterrables en el Mazo (zona privada), pues no se verifican requisitos de juego al buscar. Las Hijas del Caldero traídas se destruyen al inicio de la Fase Final.","buscar zona privada indestructible"),
F("Ptolomeo III","Debe estar en juego para hacer daño; un removal masivo de Faraones (Qadesh) no dispara el daño.","disparada salir del juego"),
F("Traficante de Esclavos","Con la errata de mayo 2023, destruye un Aliado al inicio de la Agrupación oponente para mover los oros del rival a Oro Pagado.","errata oros"),
F("Leonidas","Solo roba una carta extra en tu Fase Final y únicamente si controlas 2 o más Héroes.","fase final robar condicion"),
F("Esna","Se dispara en el paso 4 de jugar una carta: robas primero y luego el Aliado puede ser anulado.","pasos jugar carta anulado"),
F("Forma de Toro","No es jugada válida con Corona de Arturo si debes destruir un oro en la Fase Final y no puedes cumplirlo (requisito de poder cumplir el efecto).","requisito valido"),
F("Corona de Arturo","Con ella en juego, Mercaderes sí se destruye en la Fase Final si ya no hay 2 Aliados, pues el efecto de considerarse Aliado terminó antes.","considerar aliado fase final")];

const F6=(t,card,alts,txt,tags)=>({id:"g26-"+card.toLowerCase().replace(/\W+/g,"-"),t,card,alts,txt,tags:(tags||"")+" "+t+" "+alts.join(" "),src:"faq26",tipo:"aclaración oficial",ed:PB+" · FAQ mayo 2026",k:"aclaración"});
FAQ.push(
F6("Ojo Udyat + Abismo","Ojo Udyat",["Abismo"],"Sí se puede: Ojo Udyat se dispara cuando el oponente juega una carta (paso 4 de DAR 4.5.3) y en el paso 5 puedes anular la carta jugada con Abismo, incluso el Aliado que disparó Ojo Udyat.","anular pasos jugar carta respuesta"),
F6("Mut","Mut",[],"La habilidad activada de Mut tiene 2 acciones que se hacen al mismo tiempo y no se condicionan entre sí: con el primer efecto puedes robar 1 carta aunque algún jugador no destierre una carta de su cementerio (por no tener cartas o porque un efecto lo impida). El segundo efecto solo se resuelve si el primero se resolvió por completo: robaste, ambos jugadores desterraron una carta de su cementerio y tienes más cartas en tu destierro que tu oponente.","mut robar desterrar cementerio completo"),
F6("Mut + Cinturón de Lady Ann","Mut",["Cinturón de Lady Ann"],"Las dos acciones de Mut ocurren a la vez y no se condicionan: robas 1 aunque nadie destierre del cementerio (por no tener cartas o por Cinturón de Lady Ann). El segundo efecto solo se resuelve si el primero se completó: robaste, ambos desterraron una carta y tienes más cartas en tu destierro.","robar desterrar cementerio completo"),
F6("Gea","Gea",["Nudo de Isis"],"No puedes activar Gea si un jugador no tiene cartas en el cementerio o si un efecto impide barajarlas (Nudo de Isis), porque es un coste de activación para ambos. Solo si ambos barajan, robas 1 con su segunda habilidad.","coste activacion barajar cementerio"),
F6("Beni Hassam + Apophis","Beni Hassam",["Apophis"],"Prevalece la habilidad continua del Tótem: mientras Beni Hassam esté en juego no se declara ataque ni se hace botar al oponente, así que Apophis no hace botar 3 cartas.","continua prevalece daño directo"),
F6("Aliados con salida y tope del Castillo","Eter",["Focea","Sir Lamorak","Bob Derg","Aquiles","Djedefhor","Sir Persival"],"Si un Aliado con habilidad de salida es puesto en el tope del Castillo, su controlador resuelve primero esa habilidad y luego el Aliado queda en el tope (Lamorak, Bob Derg, Aquiles roban; Djedefhor baraja). Con efectos que barajan al Aliado (Sir Persival), primero se baraja y luego se resuelve la salida.","salida tope castillo orden"),
F6("Nudo de Isis","Nudo de Isis",["Kilgharrah","Cruzar la Puerta"],"Con Nudo de Isis en tu Reserva no puedes barajar del cementerio: no activas Gea ni Kilgharrah (barajar es su coste), pero sí puedes jugar Cruzar la Puerta, cuyo único requisito es un objetivo válido.","reserva oro barajar coste requisito"),
F6("Relámpago Arcano con Magia Amatista, Danza de Sangre y Ataque Fulminante","Magia Amatista",["Danza de Sangre","Ataque Fulminante","Relámpago Arcano"],"Solo puedes redirigir a objetivos que cumplan la elección original: otra copia del Aliado desterrado (Magia Amatista), una carta de fuerza 3 o menos / coste 3 o más según lo elegido (Danza de Sangre), o un Aliado del mismo coste o fuerza elegido (Ataque Fulminante).","redirigir objetivo valido"),
F6("Ay, Amyrteos, Nemty, Mesa Redonda y Renpet","Nemty",["Ay","Amyrteos","Mesa Redonda","Renpet"],"Primero se resuelve por completo la habilidad activada (Ay roba 2; Nemty baraja una carta oponente) y después la disparada de salida (Amyrteos busca un Oro; Mesa Redonda destruye un Oro; Renpet).","activada salida orden completo"),
F6("Varias habilidades disparadas a la vez (DAR 4.6.7)","Corona Faraónica",["Nephre-Ka","Corona del Día","Dionisio Zagreo"],"Si un mismo jugador dispara dos o más efectos a la vez, él ordena su resolución a su elección. Corona Faraónica exige controlar ya un Aliado Faraón para dispararse.","disparadas orden simultaneo eleccion"),
F6("Hateshesput y Kefrén","Hateshesput",["Kefrén"],"Hateshesput puede barajarse a sí misma pagando 2 oros aunque haya más copias, pues usas su propia habilidad. Si Kefrén (en Línea de Defensa) fijó a Hateshesput, ésta no puede salir del juego y no puedes barajarla.","inmune habilidades barajar salir del juego"),
F6("Orden de la Fase Final (DAR 5.4)","Látigo y Bastón",["Forma de Lince","Guerrero Escorpión"],"Primero se juegan cartas y habilidades de la Fase Final (Látigo y Bastón, si controlas un Guerrero). Después se roban las cartas extra por habilidades (Forma de Lince, Guerrero Escorpión) si cumples sus requisitos.","fase final orden robar extra"),
F6("Loops de habilidades","Diente de la Bestia",["Cleopatra VII","Alejandro Magno","Cathach","Águila Imperial","Duque Godofredo"],"Cuando un efecto termina y su propia consecuencia lo vuelve a aplicar, queda en loop: Cleopatra VII nombrada Héroe y tomada con Alejandro Magno queda sin habilidad; igual un Aliado con Cathach, Águila Imperial y Duque Godofredo queda con fuerza 1 y sin habilidad.","loop bucle perder habilidad"),
F6("Cancelar habilidades disparadas","Guerrero de la Libertad",["Meleagro","Melchor","Kilgharrah","Altar del Bosque","Desafiar a Arturo","Baltazar"],"Guerrero de la Libertad y Meleagro tienen habilidades disparadas, así que se pueden cancelar (Desafiar a Arturo, Siete contra Tebas, Altar del Bosque, Baltazar). De Melchor puedes cancelar la búsqueda o el robo. En Gea y Kilgharrah no cancelas el coste de barajar, solo el robo.","cancelar disparada coste"),
F6("Ib-Mut","Ib-Mut",[],"Su habilidad disparada de entrada es obligatoria si hay cartas barajables: puede barajar solo el controlador, solo el oponente o ambos. Solo si ambos barajaron se completa y puedes pagar este Oro para robar 1 carta.","oro obligatoria barajar completo"),
F6("Capa de Invisibilidad (secuencias)","Capa de Invisibilidad",["Sir Gaheris","Amergin el Druida","Rey Arturo Pendragón"],"Si barajan al Aliado en respuesta a su entrada, su habilidad disparada igual se resuelve (Amergin trae a Tadg; Arturo juega a Yvain). Con Sir Gaheris sin otros Aliados, juegas el Arma sobre él, resuelves su habilidad y luego Gaheris y el Arma se barajan.","capa invisibilidad barajar disparada"),
F6("Desterrar una sola carta: Anillos de Badbury y Homunculus","Anillos de Badbury",["Homunculus","Cinturón de Lady Ann"],"No se puede desterrar solo 1 carta: tu oponente necesita al menos 2 cartas desterrables en el cementerio. Con Cinturón de Lady Ann en la Reserva no puedes activar Anillos ni jugar Homunculus.","desterrar dos cartas cementerio"),
F6("Reducciones de coste","Yvain del León",["Martillo Pesado","Galatine","Forma de Niebla"],"Reducir el coste solo vale al momento de jugar la carta: para efectos de juego prevalece el coste impreso. Por eso Forma de Niebla (anula coste 2 o menos) no anula un Arma cuyo coste fue reducido por Yvain del León.","reducir coste impreso anular"),
F6("Macda Tho y Torc Fianna","Macda Tho",["Torc Fianna"],"Torc Fianna es continua (+1 fuerza desde la declaración de ataque); Macda Tho se dispara en la asignación de bloqueo. Prevalece Macda Tho: los atacantes no bloqueados tienen fuerza 1 hasta la Fase Final, salvo otro modificador posterior.","continua disparada fuerza prevalece"),
F6("Objetivos redundantes sobre Imbloqueables","Berserk",["Ataúd de Ramsés","Orcos","Erastóstenes","Sakraham"],"Sí puedes: el objetivo es válido si se dirige bien y el efecto se resuelve en lo posible, aunque sea redundante (por ejemplo dar Imbloqueable a un Aliado ya Imbloqueable).","objetivo valido redundante imbloqueable"),
F6("Aliado Feérico","Aliado Feérico",["Draco Pútrido","Isengrim el Lobo","Reynard el Zorro"],"Se juega en respuesta a recibir daño directo, o en la Asignación de Daño para daño de combate: destruyes un Aliado tuyo y ese daño pasa a 0. Luego se resuelve la salida del Aliado destruido.","daño directo combate reducir cero"),
F6("Pasos de la Asignación de Daño (a–e)","Nuada Brazo de Plata",["Orcos","Teseo de Atenas"],"a) respuestas; b) se calcula la diferencia de fuerzas; c) el Castillo recibe el daño no cubierto; d) los Aliados son destruidos por combate; e) se disparan las habilidades de daño de combate y después las de los destruidos. Orcos y Teseo exigen 2 o más Aliados Sombra/Héroe en el punto e. Varias copias de Nuada se disparan juntas pero se resuelven una a una.","asignacion daño pasos orden disparadas"),
F6("Cancelaciones de ataque","Las Tres Olas",["Flechas de Lava","Ares","Figol el Druida","Medjay","Ramsés IX"],"Si cancelas la declaración con Las Tres Olas o Flechas de Lava, los atacantes vuelven a la Línea de Defensa, sus habilidades de declaración no se disparan y se pasa a la Fase Final. Ares cancela en Guerra de Talismanes y las fases siguientes continúan. Figol el Druida no cancela el ataque: los atacantes vuelven a Defensa pero sus habilidades de bloqueo sí se disparan.","cancelar ataque bloqueo fase final"),
F6("Barajar cartas del cementerio","Caoranach",["Baal-Zaphon","Atenea","Espartaco","Virgilio","Escudo Celestial","Moy-Mell","Látigo y Bastón"],"Las cartas barajadas del cementerio se muestran al oponente. Caoranach necesita al menos 1 carta y no puede barajar al Aliado que se destruye; Baal-Zaphon, Atenea, Espartaco, Ptah y Olabisi barajan todas si tienes menos de las indicadas; Virgilio necesita 2; Látigo y Bastón exactamente 2.","barajar cementerio mostrar cantidad"),
F6("Bonos permanentes en cartas convertidas en Aliado","Ave de Hera",["Ave Ardea","Guiza","Clochafarmore","Locura de Heracles"],"Un bono de fuerza permanente aplicado a un Oro convertido en Aliado (o a un Tótem considerado Aliado) no se pierde en la Fase Final; solo se pierde si esa carta sale del juego.","permanente fuerza convertir considerar"),
F6("Congelar Traidor","Congelar Traidor",["Mercaderes","Guiza"],"Ganas el control del Aliado oponente por el resto del juego. En la Fase Final, si esa carta convertida o considerada Aliado no salió del juego, va a la zona que le corresponde de su nuevo controlador (Oros a Oro Pagado o Reserva según su origen; Tótem a la Línea de Apoyo).","control convertido fase final zona"),
F6("Kamose el Guerrero","Kamose el Guerrero",["Leucrota","Guerrero Escorpión"],"Su prevención puede usarse incluso si él mismo está siendo afectado (p. ej. por Leucrota). En combate, al activarla, los Aliados dejan la comparación de fuerzas: el bloqueador no se destruye, Kamose se baraja y el Guerrero prevenido queda en juego.","prevencion comparacion fuerza"),
F6("Jerusalén","Jerusalén",[],"Con Jerusalén en juego se omite la Fase de Agrupación: no se agrupan oros ni Aliados y no se disparan habilidades ligadas a esa fase. Como un Aliado necesita haber pasado una Agrupación bajo tu control, ninguno puede ser declarado atacante.","agrupacion omitir atacar"),
F6("Prevención entre varias cartas","Ptolomeo II",["Hera","Kamose el Guerrero","Gruagash","Qadesh","Rayos","Guardia Gozosa","Anubis","Apophis"],"Ante efectos masivos (Gruagash, Qadesh, Rayos, Guiza) la prevención de Ptolomeo II, Hera y Kamose salva solo a un Aliado. La habilidad continua de Apophis o Cleopatra VII no puede prevenirse el turno en que el Aliado entra. Guardia Gozosa y Anubis sí pueden prevenirse por completo.","prevencion masivo continua"),
F6("Quitar habilidad a una carta sin habilidad","Averix el Sabio",["Drácula","Diente de la Bestia","Takelot","Temístocles","Carnwennan","Apophis"],"Un mismo objetivo no puede afectarse dos veces con Averix, Drácula o Diente de la Bestia, pues ya no tiene habilidad (no es objetivo válido); Takelot o Temístocles sí pueden nombrar la misma carta otra vez. Con Apophis y Carnwennan, Relámpago Arcano solo redirige a una carta que no sea Aliado y tenga habilidad (Tótem o Arma).","perder habilidad objetivo valido redirigir"),
F6("Anulaciones: Invocar Chacales, César Augusto y Linaje Celta","Invocar Chacales",["César Augusto","Linaje Celta"],"Invocar Chacales anula una carta que anule una tuya, por lo que no anula la habilidad disparada de César Augusto (esa solo se cancela). Linaje Celta hace que el próximo Aliado Desafiante no pueda ser anulado ni afectado por César Augusto.","anular cancelar disparada"),
F6("Micenas","Micenas",["Capa de Invisibilidad","Bola de Energía","Levantar a los Muertos","Dragón Dorado","Fe sin Límites","Invocar Chacales"],"Aumenta en 2 el coste de las cartas jugadas en respuesta (Capa de Invisibilidad, Bola de Energía, Levantar a los Muertos) y de anulación (Dragón Dorado, Fe sin Límites, Invocar Chacales). No afecta a prevención (Abu Simbel, Hera, Ptolomeo) ni a cancelación (Siete contra Tebas, Desafiar a Arturo).","coste respuesta anulacion prevencion cancelacion"));
RULES.push({id:"r-45-3",t:"Pasos 4 y 5 de jugar una carta (DAR 4.5.3)",txt:"Según la FAQ 2026: las habilidades que se disparan al jugar una carta del oponente ocurren en el paso 4, y en el paso 5 puedes activar una habilidad de anulación contra la carta jugada.",tags:"pasos jugar carta anular paso 4 paso 5",src:"faq26",tipo:"aclaración oficial",ed:PB,k:"regla"});

const RES26={
"Mut":["Activas la habilidad de Mut; sus dos acciones ocurren a la vez y ninguna depende de la otra.","Primer efecto: robas 1 carta, aunque algún jugador no pueda o no destierre una carta de su cementerio.","Segundo efecto: solo si el primero se resolvió por completo (robaste y ambos desterraron una carta del cementerio) y además tienes más cartas en tu destierro que tu oponente."],
"Mut + Cinturón de Lady Ann":["Cinturón de Lady Ann está en la Reserva de Oros: las cartas de los cementerios no pueden desterrarse.","Activas Mut: el primer efecto (robar 1 carta) sí se resuelve, porque no depende del destierro.","El segundo efecto no se resuelve: nadie desterró una carta, así que el primer efecto no se completó."],
"Gea":["Para activarla, ambos jugadores deben barajar 1 carta de su cementerio en su Mazo Castillo (es el coste).","Si un jugador no tiene cartas en el cementerio, o un efecto lo impide (Nudo de Isis), no puedes activarla.","Si ambos barajaron, puedes robar 1 carta con su segunda habilidad."],
"Ib-Mut":["Al entrar en juego, su disparada obliga a barajar 1 carta del cementerio a cada jugador que pueda.","Puede barajar solo el controlador, solo el oponente o ambos.","Solo si ambos barajaron y la disparada se resolvió completa, puedes pagar este Oro para robar 1 carta."],
"Nudo de Isis":["Con Nudo de Isis en tu Reserva de Oros, las cartas de los cementerios no pueden barajarse.","Gea y Kilgharrah no pueden activarse, porque barajar es su coste.","Cruzar la Puerta sí puede jugarse: solo exige un objetivo válido (destruir una carta que no sea Oro)."],
"Ojo Udyat":["El oponente juega una carta: ocurre el paso 4 de DAR 4.5.3 y puedes disparar Ojo Udyat.","Juegas Abismo para anular un Aliado que se está jugando.","En el paso 5 se activa la anulación y puedes anular incluso el Aliado que disparó Ojo Udyat."],
"Eter":["Una carta (Éter, Focea) pone a un Aliado en el tope del Castillo de su dueño.","Si el Aliado tiene salida, su controlador la resuelve primero: Lamorak, Bob Derg y Aquiles roban; Djedefhor baraja.","Luego el Aliado queda en el tope. Con efectos que lo barajan (Sir Persival), primero se baraja y después se resuelve la salida."],
"Nuada Brazo de Plata":["a) Se juegan respuestas en la Asignación de Daño.","b) Se calcula la diferencia de fuerzas entre atacantes y bloqueadores.","c) El Castillo defensor recibe el daño no cubierto.","d) Los Aliados son destruidos por daño de combate.","e) Se disparan las habilidades de Aliados que hicieron daño (Nuada, Orcos, Teseo) y luego las de los destruidos. Orcos y Teseo necesitan 2 o más Aliados Sombra/Héroe en este punto."],
"Las Tres Olas":["Cancelas la declaración de ataque (Las Tres Olas o Flechas de Lava).","Los atacantes vuelven a la Línea de Defensa y no se disparan sus habilidades de declaración (Medjay, Ramsés IX).","Se omiten las fases posteriores y se pasa a la Fase Final.","Distinto: Ares cancela en Guerra de Talismanes y las fases siguientes continúan; Figol el Druida no cancela el ataque."],
"Capa de Invisibilidad":["El oponente juega Capa de Invisibilidad y baraja tu Aliado recién jugado.","Su habilidad disparada de entrada igual se resuelve (Amergin trae a Tadg; Arturo juega a Yvain).","Sir Gaheris sin otros Aliados: juega el Arma sobre sí mismo, resuelve el Arma y recién entonces Gaheris y el Arma se barajan."],
"Kamose el Guerrero":["Puedes activar su prevención incluso si él está siendo afectado.","En combate, al activarla, los Aliados dejan la comparación de fuerzas.","Los bloqueadores no se destruyen, Kamose se baraja y el Guerrero prevenido sigue en juego."],
"Jerusalén":["Mientras esté en juego, se omite la Fase de Agrupación.","No se agrupan oros ni Aliados y no se usan habilidades ligadas a esa fase.","Un Aliado necesita haber pasado una Agrupación bajo tu control para atacar: ninguno puede ser declarado atacante."],
"Macda Tho":["Torc Fianna (continua) da +1 fuerza a los Aliados que pasan a la Línea de Ataque.","Macda Tho se dispara en la asignación de bloqueo, al ver qué Aliados no fueron bloqueados.","Prevalece Macda Tho: esos Aliados tienen fuerza 1 hasta la Fase Final, salvo un modificador posterior."],
"Aliado Feérico":["Te van a hacer daño directo, o estás en la Asignación de Daño de combate.","Juegas Aliado Feérico y destruyes un Aliado tuyo: ese daño pasa a 0.","Luego resuelves la disparada de salida del Aliado destruido (Draco Pútrido, Isengrim, Reynard)."],
"Congelar Traidor":["Ganas el control de un Aliado oponente por el resto del juego.","Si es un Oro convertido o un Tótem considerado Aliado, en la Fase Final va a la zona de tu lado.","Oros: Oro Pagado o Reserva según su origen; Tótem: Línea de Apoyo."],
"Anillos de Badbury":["Para activar Anillos o jugar Homunculus, tu oponente debe tener al menos 2 cartas desterrables en el cementerio.","No se puede desterrar solo 1.","Si tu oponente tiene Cinturón de Lady Ann en la Reserva, no puedes hacerlo."],
"Micenas":["Con Micenas en juego, sube 2 el coste de las cartas de respuesta (Capa de Invisibilidad, Bola de Energía, Levantar a los Muertos) y de anulación (Dragón Dorado, Fe sin Límites, Invocar Chacales).","Paga el coste aumentado al jugarlas.","Prevención y cancelación (Abu Simbel, Hera, Ptolomeo, Siete contra Tebas, Desafiar a Arturo) no se ven afectadas."]};
const RES23={
"Relámpago Arcano":["El oponente juega una carta o activa una habilidad que afecta a una carta tuya que no sea Oro.","Inmediatamente juegas Relámpago Arcano.","Si el efecto es global (Kenneth I, Thanatos, Aplastar Fomor), no puede redirigirse.","Si no, eliges un nuevo objetivo válido para la habilidad mandante de la carta original.","La fuente del efecto nunca puede ser el nuevo objetivo (autorreferencia, DAR 4.6.11)."],
"Santo Grial":["Pagas el coste de activación que destruye una carta tuya.","Juegas Santo Grial sobre el Aliado destruido: sube a tu mano (su Arma va con él).","El efecto de la carta que lo destruyó no se resuelve, porque exigía que el Aliado quedara destruido."],
"Siete contra Tebas":["Tu oponente activa o dispara una habilidad de una carta en juego.","Si es activada o disparada, la cancelas con Siete contra Tebas (primero pagas su coste de activación).","Si es continua, no puede cancelarse."],
"Antropófagos":["El objetivo debe ser un Aliado que pueda ser destruido en la Fase Final.","Con un Aliado Indestructible no es jugada válida.","Con Aliados que solo tienen Prevención (Ra, Rey Arturo Pendragón) sí se puede jugar."],
"Goblin Maligno":["Su efecto se dispara en respuesta a la declaración de ataque.","El jugador activo tiene la prioridad: primero se aplica la bonificación.","Si luego el oponente juega Congelar, ya no cambia la bonificación recibida."]};
FAQ.forEach(f=>{const R=f.src==="faq26"?RES26:RES23,m=R[f.t]||R[f.card];if(m&&m[0])f.res=m});
const PAR=new Set(["Mut + Cinturón de Lady Ann","Ojo Udyat + Abismo","Beni Hassam + Apophis","Macda Tho y Torc Fianna","Relámpago Arcano con Magia Amatista, Danza de Sangre y Ataque Fulminante"]);
